/// <summary>
/// As per CB223 Pallet Rounding, rounding policy is executed for Pallets and Layers.This class is used prepare an ordered list of enumeration values for <c>METRoundingPolicyType</c> enum.
/// </summary>
public class METPalletRoundingPolicyTypeOrderedList implements Enumerable
{
    List palletRoundingPolicyTypeOrderedList;

}

Method.Source:
/// <summary>
/// Get the enumerator of the ordered list.
/// </summary>
/// <returns>An instance of <c>ListEnumerator</c> class.</returns>
public Enumerator getEnumerator()
{
    return palletRoundingPolicyTypeOrderedList.getEnumerator();
}

/// <summary>
/// Initialization of local varaibles during creation of class <c>METPalletRoundingPolicyTypeOrderedList</c> object.
/// </summary>
protected void new()
{
    palletRoundingPolicyTypeOrderedList = new List(Types::Enum);

    this.initializePalletRoundingPolicyTypeOrderedList();
}

/// <summary>
/// Set list in ascending or descending order
/// </summary>
/// <param name = "_enumerateInOrder">Ascending or descending order</param>
private void setEnumerateInOrder(SortOrder _enumerateInOrder)
{
    if (_enumerateInOrder == SortOrder::Descending)
    {
        this.reverseOrderedList();
    }
}

/// <summary>
/// Reverse the ordered list
/// </summary>
private void reverseOrderedList()
{
    List reversedPalletRoundingPolicyTypeOrderedList = new List(Types::Enum);
    ListEnumerator enumerator = this.getEnumerator() as ListEnumerator;

    while (enumerator.moveNext())
    {
        reversedPalletRoundingPolicyTypeOrderedList.addStart(enumerator.current());
    }

    palletRoundingPolicyTypeOrderedList = reversedPalletRoundingPolicyTypeOrderedList;
}

/// <summary>
/// Constructs a new instance of the <c>METPalletRoundingPolicyTypeOrderedList</c> class to be enumerated in the specified order.
/// </summary>
/// <param name="_enumerateInOrder">Enumerate the values in the enum in the specified order.</param>
/// <returns>An instance of <c>METPalletRoundingPolicyTypeOrderedList</c> class.</returns>
public static METPalletRoundingPolicyTypeOrderedList newFromOrder(SortOrder _enumerateInOrder = SortOrder::Ascending)
{
    METPalletRoundingPolicyTypeOrderedList orderedList = new METPalletRoundingPolicyTypeOrderedList();
    orderedList.setEnumerateInOrder(_enumerateInOrder);
    return orderedList;
}

/// <summary>
/// Initialize the list with all the applicable values of <c>METRoundingPolicyType</c> enumeration in ascending order.
/// </summary>
protected void initializePalletRoundingPolicyTypeOrderedList()
{
    palletRoundingPolicyTypeOrderedList.addEnd(METRoundingPolicyType::Pallet);
    palletRoundingPolicyTypeOrderedList.addEnd(METRoundingPolicyType::Layer);
}
